CREATE DATABASE HOSPITAL_WAREHOUSE;
USE HOSPITAL_WAREHOUSE;
CREATE TABLE IF NOT EXISTS Facility (FacilityID TEXT, FacilityName TEXT, LocationID TEXT, ContactID TEXT, HospitalAttributesID TEXT, OverallRating TEXT, OverallRatingFootnote TEXT);
CREATE TABLE IF NOT EXISTS DimLocation (LocationID TEXT, City TEXT, State TEXT, County TEXT, Country TEXT, ZIPCode TEXT);
CREATE TABLE IF NOT EXISTS DimContact (ContactID TEXT, Address TEXT, Telephone TEXT);
CREATE TABLE IF NOT EXISTS DimHospitalAttributes (HospitalAttributesID TEXT, HospitalType TEXT, HospitalOwnership TEXT, EmergencyServices TEXT, BirthingFriendlyDesignation TEXT);
CREATE TABLE IF NOT EXISTS MortalityMeasures (FacilityID TEXT, MORTGroupMeasureCount TEXT, FacilityMORTMeasures TEXT, MORTBetter TEXT, MORTNoDifferent TEXT, MORTWorse TEXT, MORTFootnote TEXT);
CREATE TABLE IF NOT EXISTS SafetyMeasures (FacilityID TEXT, SafetyGroupMeasureCount TEXT, FacilitySafetyMeasures TEXT, SafetyBetter TEXT, SafetyNoDifferent TEXT, SafetyWorse TEXT, SafetyFootnote TEXT);
CREATE TABLE IF NOT EXISTS ReadmissionMeasures (FacilityID TEXT, READMGroupMeasureCount TEXT, FacilityREADMMeasures TEXT, READMBetter TEXT, READMNoDifferent TEXT, READMWorse TEXT, READMFootnote TEXT);
CREATE TABLE IF NOT EXISTS ExperienceAndTE (FacilityID TEXT, PtExpGroupMeasureCount TEXT, FacilityPtExpMeasures TEXT, PtExpFootnote TEXT, TEGroupMeasureCount TEXT, FacilityTEMeasures TEXT, TEFootnote TEXT);
